import { afterEach, describe, expect, it, vi } from "bun:test";
import type { ModelRegistry } from "../../config/model-registry";
import { Settings } from "../../config/settings";
import { AsyncJobManager } from "../../async";
import { TaskTool } from "../index";
import * as discoveryModule from "../discovery";
import * as executorModule from "../executor";
import type { AgentDefinition, SingleResult, TaskParams } from "../types";
import type { ToolSession } from "../../tools";

const taskAgent: AgentDefinition = {
	name: "task",
	description: "Task agent",
	systemPrompt: "Run assigned task.",
	source: "bundled",
	tools: ["read"],
};

function createToolSession(options: { asyncEnabled: boolean; maxConcurrency?: number }): ToolSession {
	const modelRegistry = {
		authStorage: undefined,
		refresh: async () => {},
		getAvailable: () => [],
		getApiKey: async () => null,
	} as unknown as ModelRegistry;
	return {
		cwd: process.cwd(),
		hasUI: false,
		settings: Settings.isolated({
			"async.enabled": options.asyncEnabled,
			"task.isolation.mode": "none",
			"task.maxConcurrency": options.maxConcurrency ?? 4,
		}),
		getSessionFile: () => null,
		getSessionSpawns: () => "*",
		getAgentId: () => "Main",
		modelRegistry,
	} as unknown as ToolSession;
}

function successResult(options: { id: string; index: number; agent: AgentDefinition; task: string; assignment?: string; description?: string }): SingleResult {
	return {
		index: options.index,
		id: options.id,
		agent: options.agent.name,
		agentSource: options.agent.source,
		task: options.task,
		assignment: options.assignment,
		description: options.description,
		exitCode: 0,
		output: `${options.id} done`,
		stderr: "",
		truncated: false,
		durationMs: 1,
		tokens: 0,
	};
}

afterEach(async () => {
	vi.restoreAllMocks();
	const manager = AsyncJobManager.instance();
	if (manager) {
		await manager.dispose();
	}
	AsyncJobManager.resetForTests();
});

describe("task scheduler dependencies", () => {
	it("fans out dependency-free tasks and waits for dependents in sync mode", async () => {
		vi.spyOn(discoveryModule, "discoverAgents").mockResolvedValue({ agents: [taskAgent], projectAgentsDir: null });

		const started: string[] = [];
		const releaseRoots = Promise.withResolvers<void>();
		const bothRootsStarted = Promise.withResolvers<void>();
		let rootStarts = 0;
		vi.spyOn(executorModule, "runSubprocess").mockImplementation(async options => {
			started.push(options.id);
			if (options.id.endsWith("Setup") || options.id.endsWith("Lint")) {
				rootStarts += 1;
				if (rootStarts === 2) {
					bothRootsStarted.resolve();
				}
				await releaseRoots.promise;
			}
			return successResult(options);
		});

		const tool = await TaskTool.create(createToolSession({ asyncEnabled: false, maxConcurrency: 3 }));
		const params: TaskParams = {
			agent: "task",
			tasks: [
				{ id: "Setup", description: "Setup", assignment: "setup" },
				{ id: "Lint", description: "Lint", assignment: "lint" },
				{ id: "Deploy", description: "Deploy", assignment: "deploy", blockedBy: ["Setup", "Lint"] },
			],
		};

		const resultPromise = tool.execute("tool-call", params);
		await bothRootsStarted.promise;
		expect(started.slice(0, 2).map(id => id.replace(/^\d+-/, "")).sort()).toEqual(["Lint", "Setup"]);
		expect(started.map(id => id.replace(/^\d+-/, ""))).not.toContain("Deploy");

		releaseRoots.resolve();
		const result = await resultPromise;
		expect(started.map(id => id.replace(/^\d+-/, ""))).toEqual(["Setup", "Lint", "Deploy"]);
		expect(result.details?.results.map(entry => entry.exitCode)).toEqual([0, 0, 0]);
	});

	it("skips dependent tasks after a failed dependency in sync mode", async () => {
		vi.spyOn(discoveryModule, "discoverAgents").mockResolvedValue({ agents: [taskAgent], projectAgentsDir: null });

		const started: string[] = [];
		vi.spyOn(executorModule, "runSubprocess").mockImplementation(async options => {
			started.push(options.id);
			if (options.id.endsWith("Setup")) {
				return {
					...successResult(options),
					exitCode: 1,
					stderr: "setup failed",
					error: "setup failed",
				};
			}
			return successResult(options);
		});

		const tool = await TaskTool.create(createToolSession({ asyncEnabled: false, maxConcurrency: 2 }));
		const result = await tool.execute("tool-call", {
			agent: "task",
			tasks: [
				{ id: "Setup", description: "Setup", assignment: "setup" },
				{ id: "Deploy", description: "Deploy", assignment: "deploy", blockedBy: ["Setup"] },
			],
		} satisfies TaskParams);

		expect(started.map(id => id.replace(/^\d+-/, ""))).toEqual(["Setup"]);
		expect(result.details?.results.map(entry => entry.exitCode)).toEqual([1, 1]);
		expect(result.details?.results[1]?.stderr).toContain("Blocked by failed dependency: Setup");
	});

	it("normalizes task ids and dependencies symmetrically before lookup", async () => {
		vi.spyOn(discoveryModule, "discoverAgents").mockResolvedValue({ agents: [taskAgent], projectAgentsDir: null });
		const runSubprocess = vi.spyOn(executorModule, "runSubprocess").mockImplementation(async options => successResult(options));

		const tool = await TaskTool.create(createToolSession({ asyncEnabled: false, maxConcurrency: 2 }));
		const result = await tool.execute("tool-call", {
			agent: "task",
			tasks: [
				{ id: " Setup ", description: "Setup", assignment: "setup" },
				{ id: "Deploy", description: "Deploy", assignment: "deploy", blockedBy: ["setup"] },
			],
		} satisfies TaskParams);

		expect(result.details?.results.map(entry => entry.exitCode)).toEqual([0, 0]);
		expect(runSubprocess).toHaveBeenCalledTimes(2);
	});

	it("rejects unknown dependencies before scheduling work", async () => {
		vi.spyOn(discoveryModule, "discoverAgents").mockResolvedValue({ agents: [taskAgent], projectAgentsDir: null });
		const runSubprocess = vi.spyOn(executorModule, "runSubprocess").mockImplementation(async options => successResult(options));

		const tool = await TaskTool.create(createToolSession({ asyncEnabled: false, maxConcurrency: 2 }));
		const result = await tool.execute("tool-call", {
			agent: "task",
			tasks: [
				{ id: "Setup", description: "Setup", assignment: "setup" },
				{ id: "Deploy", description: "Deploy", assignment: "deploy", blockedBy: ["Missing"] },
			],
		} satisfies TaskParams);

		expect(result.content[0]?.type).toBe("text");
		expect(result.content[0]?.text).toContain("Invalid tasks: Unknown task dependencies: Deploy -> Missing");
		expect(runSubprocess).not.toHaveBeenCalled();
	});

	it("rejects self dependencies after normalization", async () => {
		vi.spyOn(discoveryModule, "discoverAgents").mockResolvedValue({ agents: [taskAgent], projectAgentsDir: null });
		const runSubprocess = vi.spyOn(executorModule, "runSubprocess").mockImplementation(async options => successResult(options));

		const tool = await TaskTool.create(createToolSession({ asyncEnabled: false, maxConcurrency: 1 }));
		const result = await tool.execute("tool-call", {
			agent: "task",
			tasks: [{ id: " Setup ", description: "Setup", assignment: "setup", blockedBy: ["setup"] }],
		} satisfies TaskParams);

		expect(result.content[0]?.type).toBe("text");
		expect(result.content[0]?.text).toContain("Invalid tasks: Self dependencies are not allowed");
		expect(runSubprocess).not.toHaveBeenCalled();
	});

	it("rejects cyclic dependencies before scheduling work", async () => {
		vi.spyOn(discoveryModule, "discoverAgents").mockResolvedValue({ agents: [taskAgent], projectAgentsDir: null });
		const runSubprocess = vi.spyOn(executorModule, "runSubprocess").mockImplementation(async options => successResult(options));

		const tool = await TaskTool.create(createToolSession({ asyncEnabled: false, maxConcurrency: 2 }));
		const result = await tool.execute("tool-call", {
			agent: "task",
			tasks: [
				{ id: "Setup", description: "Setup", assignment: "setup", blockedBy: ["Deploy"] },
				{ id: "Deploy", description: "Deploy", assignment: "deploy", blockedBy: ["Setup"] },
			],
		} satisfies TaskParams);

		expect(result.content[0]?.type).toBe("text");
		expect(result.content[0]?.text).toContain("Invalid tasks: Cyclic task dependencies detected: Setup -> Deploy -> Setup");
		expect(runSubprocess).not.toHaveBeenCalled();
	});

	it("rejects duplicate task ids after trimming and case-folding", async () => {
		vi.spyOn(discoveryModule, "discoverAgents").mockResolvedValue({ agents: [taskAgent], projectAgentsDir: null });
		const runSubprocess = vi.spyOn(executorModule, "runSubprocess").mockImplementation(async options => successResult(options));

		const tool = await TaskTool.create(createToolSession({ asyncEnabled: false, maxConcurrency: 2 }));
		const result = await tool.execute("tool-call", {
			agent: "task",
			tasks: [
				{ id: "Setup", description: "Setup", assignment: "setup" },
				{ id: " setup ", description: "Duplicate Setup", assignment: "setup duplicate" },
			],
		} satisfies TaskParams);

		expect(result.content[0]?.type).toBe("text");
		expect(result.content[0]?.text).toContain("Invalid tasks: Duplicate task ids detected (case-insensitive)");
		expect(runSubprocess).not.toHaveBeenCalled();
	});

	it("deduplicates repeated dependency references when reporting blocked failures", async () => {
		vi.spyOn(discoveryModule, "discoverAgents").mockResolvedValue({ agents: [taskAgent], projectAgentsDir: null });

		const started: string[] = [];
		vi.spyOn(executorModule, "runSubprocess").mockImplementation(async options => {
			started.push(options.id);
			if (options.id.endsWith("Setup")) {
				return {
					...successResult(options),
					exitCode: 1,
					stderr: "setup failed",
					error: "setup failed",
				};
			}
			return successResult(options);
		});

		const tool = await TaskTool.create(createToolSession({ asyncEnabled: false, maxConcurrency: 3 }));
		const result = await tool.execute("tool-call", {
			agent: "task",
			tasks: [
				{ id: "Setup", description: "Setup", assignment: "setup" },
				{ id: "Lint", description: "Lint", assignment: "lint" },
				{
					id: "Deploy",
					description: "Deploy",
					assignment: "deploy",
					blockedBy: ["Setup", " setup ", "Lint"],
				},
			],
		} satisfies TaskParams);

		expect(started.map(id => id.replace(/^\d+-/, "")).sort()).toEqual(["Lint", "Setup"]);
		expect(result.details?.results.map(entry => entry.exitCode)).toEqual([1, 0, 1]);
		expect(result.details?.results[2]?.stderr).toBe("Blocked by failed dependency: Setup");
	});

	it("keeps background tasks pending until dependencies complete", async () => {
		vi.spyOn(discoveryModule, "discoverAgents").mockResolvedValue({ agents: [taskAgent], projectAgentsDir: null });
		AsyncJobManager.setInstance(
			new AsyncJobManager({
				onJobComplete: async () => {},
				maxRunningJobs: 8,
			}),
		);

		const started: string[] = [];
		const releaseSetup = Promise.withResolvers<void>();
		const setupStarted = Promise.withResolvers<void>();
		vi.spyOn(executorModule, "runSubprocess").mockImplementation(async options => {
			started.push(options.id);
			if (options.id.endsWith("Setup")) {
				setupStarted.resolve();
				await releaseSetup.promise;
			}
			return successResult(options);
		});

		const tool = await TaskTool.create(createToolSession({ asyncEnabled: true, maxConcurrency: 2 }));
		const result = await tool.execute("tool-call", {
			agent: "task",
			tasks: [
				{ id: "Setup", description: "Setup", assignment: "setup" },
				{ id: "Deploy", description: "Deploy", assignment: "deploy", blockedBy: ["Setup"] },
			],
		} satisfies TaskParams);

		expect(result.content[0]?.type).toBe("text");
		await setupStarted.promise;
		expect(started.map(id => id.replace(/^\d+-/, ""))).toEqual(["Setup"]);

		releaseSetup.resolve();
		await AsyncJobManager.instance()!.waitForAll();
		expect(started.map(id => id.replace(/^\d+-/, ""))).toEqual(["Setup", "Deploy"]);
	});
});
